import { UtteranceType, type UnionEventType } from "../../types";
import { isUtterance } from "../../utils";

/**
 * Resolves the text of the user message that triggered a skill activation.
 *
 * The engine stamps only the triggering message's `originalTimestamp` on the
 * skill_activated event (not the text itself), so the text is looked up here by
 * matching that timestamp against the user utterances in the conversations.
 * Returns undefined when the timestamp is absent or no user utterance matches.
 */
export function resolveTriggeringMessage(
  conversations: readonly { readonly events: readonly UnionEventType[] }[],
  timestamp: number | undefined,
): string | undefined {
  if (timestamp === undefined) return undefined;
  for (const conversation of conversations) {
    for (const event of conversation.events) {
      if (
        isUtterance(event) &&
        event.type === UtteranceType.User &&
        event.originalTimestamp === timestamp
      ) {
        return event.text ?? undefined;
      }
    }
  }
  return undefined;
}
